/**
 * Records a false-positive sanctions disposition against one of the demonstration
 * businesses, so the compliance console shows a real worked example of a match being
 * assessed and cleared with reasoning rather than simply not firing.
 */
export async function seedSanctionsFalsePositive(ctx) {
    const { db } = ctx;
    const candidate = await maybeOne(db, `SELECT sc.id, sc.organization_id
       FROM screening_case sc
       JOIN organization o ON o.id = sc.organization_id
      WHERE sc.status IN ('potential_match','confirmed_match')
        AND o.onboarding_status = 'approved'
        AND sc.disposition IS NULL
      ORDER BY sc.requested_at LIMIT 1`);
    if (!candidate)
        return;
    await orgService.disposeScreening(db, {
        screeningCaseId: candidate.id,
        disposition: 'cleared',
        reason: 'Assessed as a false positive. The matched list entry is a different individual: the date of ' +
            'birth differs by more than a decade, the nationality does not correspond, and the middle name ' +
            'on the list entry is absent from our record. The similarity is confined to a common surname. ' +
            'Identity documents on file were re-checked against the list entry before clearing. Reviewed ' +
            'and cleared by a compliance analyst.',
        userId: ctx.users['analyst'],
        role: 'compliance_analyst',
    });
}
